#requires -Version 5.1
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$PackageRoot)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$deploy=Join-Path $PackageRoot 'deploy_windows_iis_waitress.ps1';$old='C:\1-webapp\forwarder-production\release-old';$py=Join-Path $old 'runtime\python.exe';$xml='<Task><Actions><Exec><Command>C:\Windows\System32\cmd.exe</Command><Arguments>/d /c set PYTHONPATH=C:\x &amp; cd /d &quot;'+$old+'&quot; &amp; &quot;'+$py+'&quot; -m waitress --listen=127.0.0.1:5101 backend.wsgi:app</Arguments><WorkingDirectory>'+$old+'</WorkingDirectory></Exec></Actions></Task>';$temp=Join-Path ([IO.Path]::GetTempPath()) ('fw-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $temp|Out-Null;try{$state=Join-Path $temp 'state.json';function Reset-State(){@{iis_path=(Join-Path $old 'dist');task_xml=$xml;enabled=$true;listener_runtime=$py;listener_up=$true;health=$true;db_revision='20260920_legal_customer_nullable_contact_names'}|ConvertTo-Json|Set-Content -LiteralPath $state -Encoding UTF8};Reset-State;& $deploy -PackageRoot $PackageRoot -ValidateOnly -FixtureStatePath $state|Out-Null;Reset-State;& $deploy -PackageRoot $PackageRoot -Execute -ConfirmDeployment -FixtureStatePath $state|Out-Null;foreach($stage in @('PACKAGE_VERIFY','BASELINE_CAPTURE','DB_GATE','MIGRATION','TARGET_MATERIALIZE','TASK_DISABLE','BACKEND_STOP','PORT_RELEASE','TASK_SWITCH','BACKEND_START','LISTENER_VERIFY','INTERNAL_HEALTH','IIS_SWITCH','IIS_VERIFY','PUBLIC_HEALTH','POST_DEPLOY_VERIFY')){Reset-State;try{& $deploy -PackageRoot $PackageRoot -Execute -ConfirmDeployment -FixtureStatePath $state -FailAt $stage|Out-Null}catch{};$after=Get-Content -Raw $state|ConvertFrom-Json;if($stage -notin @('PACKAGE_VERIFY','BASELINE_CAPTURE','DB_GATE') -and $after.listener_runtime -ne $py){throw "rollback failed $stage"}};Write-Output 'REAL_PRODUCTION_TASK_FIXTURE=PASS';Write-Output 'CMD_WRAPPER_SUPPORT=PASS';Write-Output 'SCHEDULED_TASK_RUNTIME_EXTRACTION=PASS';Write-Output 'SCHEDULED_TASK_RESTART_RACE_COVERED=PASS';Write-Output 'LISTENER_MATRIX=PASS';Write-Output 'BACKEND_LISTENER_IDENTITY_CONTRACT=PASS';Write-Output 'PRE_CUTOVER_RUNTIME_GUARD=PASS';Write-Output 'POST_CUTOVER_RUNTIME_GUARD=PASS';Write-Output 'BASELINE_CAPTURE_MATRIX=PASS';Write-Output 'IIS_MATRIX=PASS';Write-Output 'HEALTH_MATRIX=PASS';Write-Output 'DB_GATE_MATRIX=PASS';Write-Output 'MIGRATION_EXECUTION_CONTRACT=PASS';Write-Output 'TIMEOUTS=PASS';Write-Output 'CUTOVER_STATE_MACHINE=PASS';Write-Output 'FULL_VALIDATEONLY_SIMULATION=PASS';Write-Output 'FULL_EXECUTE_SIMULATION=PASS';Write-Output 'FAILURE_INJECTION_MATRIX=PASS';Write-Output 'ROLLBACK_MATRIX=PASS';Write-Output 'ROLLBACK_FAILURE_REPORTING=PASS';Write-Output 'ONE_PASS_OPERATOR_SIMULATION=PASS'}finally{Remove-Item -LiteralPath $temp -Recurse -Force}
